import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const ACTIVITY_TYPES = ['전자결재', '게시판'];
// 가정: 프로필 열람 로그의 로그인 구분은 '웹', 열람 대상 정보 유형은 '조직원 프로필'로 기록한다.
const PROFILE_LOG_LOGIN_TYPE = '웹';
const PROFILE_LOG_TARGET = '조직원 프로필';
const FALLBACK_IP = '0.0.0.0';

// 가정: 열람 권한은 다음으로 정한다.
// 전자결재: 보안문서·기안(임시저장) 문서는 기안자 본인만, 그 외 문서는 모두 열람.
// 게시판: 공개범위 ALL은 모두, DEPARTMENT는 작성자와 조회자의 주부서가 같을 때, INDIVIDUAL은 작성자 본인만.
const ACTIVITY_CTE = `
  WITH activity AS (
    SELECT CAST('전자결재' AS text) AS "activityType",
      d.title AS title,
      COALESCE(d.submitted_at, d.created_at) AS "activityAt"
    FROM approval_document d
    WHERE d.drafter_id = CAST(:employeeId AS bigint)
      AND (d.is_secret = false OR d.drafter_id = CAST(:userId AS bigint))
      AND (d.approval_status <> '기안' OR d.drafter_id = CAST(:userId AS bigint))
    UNION ALL
    SELECT CAST('게시판' AS text) AS "activityType",
      p.title AS title,
      p.created_at AS "activityAt"
    FROM post p
    WHERE p.author_id = CAST(:employeeId AS bigint)
      AND (
        p.visibility_scope = 'ALL'
        OR (p.visibility_scope = 'DEPARTMENT'
          AND (SELECT a.department_id FROM employee a WHERE a.employee_id = p.author_id)
            = (SELECT v.department_id FROM employee v WHERE v.employee_id = CAST(:userId AS bigint)))
        OR (p.visibility_scope = 'INDIVIDUAL' AND p.author_id = CAST(:userId AS bigint))
      )
  )
`;

function intOf(value: unknown, fallback: number): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Number(value);
  if (!Number.isInteger(n)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기는 정수여야 합니다.');
  }
  return n;
}

function pagingOf(q: Record<string, unknown>): { page: number; size: number } {
  const page = intOf(q['page'], 0);
  const size = intOf(q['size'], DEFAULT_SIZE);
  if (page < 0 || size < 1 || size > MAX_SIZE) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
  }
  return { page, size };
}

function employeeIdOf(req: Request): string {
  const raw = req.params['employeeId'];
  if (typeof raw !== 'string' || !/^\d+$/.test(raw)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '임직원 ID가 올바르지 않습니다.');
  }
  return raw;
}

@Controller('api/v1')
export class FnSfr03902Controller {
  @Get('/employees')
  async listEmployees(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const q = checks.queryOf(req.query);
    const keyword = typeof q['keyword'] === 'string' ? q['keyword'].trim() : '';
    if (keyword === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '검색어를 입력해 주세요.');
    }
    const { page, size } = pagingOf(q);
    const pattern = '%' + keyword.replace(/[\\%_]/g, (c) => '\\' + c) + '%';
    return transaction(async (db) => {
      const params = { pattern, size, offset: page * size };
      const items = await db.query(
        `SELECT e.employee_id AS "employeeId",
           e.name AS "name",
           d.name AS "departmentName"
         FROM employee e
         LEFT JOIN department d ON d.department_id = e.department_id
         WHERE e.name ILIKE :pattern OR d.name ILIKE :pattern
         ORDER BY e.name, e.employee_id
         LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        params,
      );
      const counted = await db.query(
        `SELECT COUNT(*) AS "total"
         FROM employee e
         LEFT JOIN department d ON d.department_id = e.department_id
         WHERE e.name ILIKE :pattern OR d.name ILIKE :pattern`,
        { pattern },
      );
      return { items, page, size, total: Number(counted[0]['total']) };
    });
  }

  @Get('/employees/:employeeId')
  async getEmployee(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const employeeId = employeeIdOf(req);
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT e.employee_no AS "employeeNo",
           e.name AS "name",
           e.email AS "email",
           e.mobile_phone AS "mobilePhone",
           d.name AS "departmentName",
           h.position_name AS "positionName"
         FROM employee e
         LEFT JOIN department d ON d.department_id = e.department_id
         LEFT JOIN hr_record h ON h.employee_id = e.employee_id
         WHERE e.employee_id = CAST(:employeeId AS bigint)`,
        { employeeId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '조직원을 찾을 수 없습니다.');
      }
      // 개인정보(이메일·휴대전화) 열람은 접속·사용 로그로 남긴다.
      await db.execute(
        `INSERT INTO access_log (employee_id, event_type, accessed_at, login_ip, login_type, target_info_type, created_at, updated_at)
         VALUES (CAST(:userId AS bigint), '개인정보열람', now(), :loginIp, :loginType, :targetInfoType, now(), now())`,
        {
          userId: user.id,
          loginIp: req.ip ?? FALLBACK_IP,
          loginType: PROFILE_LOG_LOGIN_TYPE,
          targetInfoType: PROFILE_LOG_TARGET,
        },
      );
      return rows[0];
    });
  }

  @Get('/employees/:employeeId/activities')
  async listEmployeeActivities(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const employeeId = employeeIdOf(req);
    const q = checks.queryOf(req.query);
    const rawType = q['activityType'];
    let activityType: string | null = null;
    if (rawType !== undefined && rawType !== null && rawType !== '') {
      if (typeof rawType !== 'string' || !ACTIVITY_TYPES.includes(rawType)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '업무활동 구분이 올바르지 않습니다.');
      }
      activityType = rawType;
    }
    const { page, size } = pagingOf(q);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)`,
        { employeeId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '조직원을 찾을 수 없습니다.');
      }
      const base = { employeeId, userId: user.id, activityType };
      const items = await db.query(
        ACTIVITY_CTE +
          `SELECT "activityType", title, "activityAt"
           FROM activity
           WHERE (CAST(:activityType AS text) IS NULL OR "activityType" = CAST(:activityType AS text))
           ORDER BY "activityAt" DESC
           LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { ...base, size, offset: page * size },
      );
      const counted = await db.query(
        ACTIVITY_CTE +
          `SELECT COUNT(*) AS "total"
           FROM activity
           WHERE (CAST(:activityType AS text) IS NULL OR "activityType" = CAST(:activityType AS text))`,
        base,
      );
      return { items, page, size, total: Number(counted[0]['total']) };
    });
  }
}

