import { useState } from 'react';
import {
  call,
  useData,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Field,
  TextInput,
  Select,
  ErrorText,
  DateText,
  Num,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;

function EmployeeDrawer({ id, role, onClose }: { id: number; role: string; onClose: () => void }) {
  const [activityType, setActivityType] = useState('');
  const [page, setPage] = useState(0);
  const profile = useData<Row>(
    () => call('GET', '/employees/' + id, role),
    [id],
  );
  const activities = useData<Page>(
    () => call<Page>('GET', '/employees/' + id + '/activities', role, undefined, { activityType, page, size: SIZE }),
    [id, activityType, page],
  );
  const p = profile.data;
  return (
    <Drawer title="조직원 프로필" onClose={onClose}>
      {profile.error !== '' && <ErrorText text={profile.error} />}
      {p && (
        <Pairs
          items={[
            ['사번', String(p['employeeNo'] ?? '')],
            ['성명', String(p['name'] ?? '')],
            ['부서명', String(p['departmentName'] ?? '')],
            ['직위', String(p['positionName'] ?? '')],
            ['이메일', String(p['email'] ?? '')],
            ['휴대전화번호', String(p['mobilePhone'] ?? '')],
          ]}
        />
      )}
      <h2>활동 내역</h2>
      <Field label="업무활동 구분">
        <Select
          value={activityType}
          onChange={(v) => {
            setActivityType(v);
            setPage(0);
          }}
          options={[
            ['전자결재', '전자결재'],
            ['게시판', '게시판'],
          ]}
          placeholder="전체"
        />
      </Field>
      {activities.error !== '' && <ErrorText text={activities.error} />}
      <Band total={activities.data?.total} />
      <DataTable
        columns={[
          { key: 'activityType', label: '업무활동 구분' },
          { key: 'title', label: '활동 제목' },
          { key: 'activityAt', label: '활동 일시', render: (r) => <DateText value={r['activityAt']} time /> },
        ]}
        rows={activities.data?.items ?? []}
        empty="활동 내역이 없습니다."
      />
      <Pager page={page} size={SIZE} total={activities.data?.total ?? 0} onPage={setPage} />
    </Drawer>
  );
}

export default function FnSfr03902Page({ role, notify }: PageProps) {
  const [input, setInput] = useState('');
  const [keyword, setKeyword] = useState('');
  const [page, setPage] = useState(0);
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [formError, setFormError] = useState('');

  const list = useData<Page | undefined>(
    async () => {
      if (keyword === '') {
        return undefined;
      }
      return call<Page>('GET', '/employees', role, undefined, { keyword, page, size: SIZE });
    },
    [keyword, page],
  );

  const search = () => {
    if (input.trim() === '') {
      setFormError('검색어를 입력해 주세요.');
      return;
    }
    setFormError('');
    setPage(0);
    setKeyword(input.trim());
  };

  const reset = () => {
    setInput('');
    setKeyword('');
    setPage(0);
    setFormError('');
  };

  const total = list.data?.total ?? 0;
  const searched = keyword !== '' && list.data !== undefined;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>검색 결과</h2>
        <Num value={total} />
      </section>
      <section className="box span-8">
        <h2>조직원 검색</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="이름 또는 부서 검색어" required>
            <TextInput value={input} onChange={setInput} placeholder="이름 또는 부서명" />
          </Field>
        </Filters>
        {formError !== '' && <ErrorText text={formError} />}
        {list.error !== '' && <ErrorText text={list.error} />}
      </section>
      <section className="box span-12">
        <h2>조직원 목록</h2>
        <Band total={searched ? total : undefined} />
        <DataTable
          columns={[
            { key: 'name', label: '성명' },
            { key: 'departmentName', label: '부서명' },
          ]}
          rows={list.data?.items ?? []}
          onRowClick={(row) => setSelectedId(Number(row['employeeId']))}
          empty={searched ? '검색 결과가 없습니다.' : '검색어를 입력하고 조회해 주세요.'}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {selectedId !== null && (
        <EmployeeDrawer id={selectedId} role={role} onClose={() => setSelectedId(null)} />
      )}
    </div>
  );
}
